import { create } from "zustand";
import { db_get_feed_bookmarks, db_toggle_feed_bookmark, db_remove_feed_bookmark } from "@/db/feeds";
import type { FeedBookmark, FeedBookmarkInput } from "@/hooks/useDB.types";

interface FeedBookmarksState {
  items: FeedBookmark[];
  urls: Set<string>;
  pending: Set<string>;
  loaded: boolean;
  refresh: () => Promise<void>;
  toggle: (input: FeedBookmarkInput) => Promise<boolean>;
  remove: (url: string) => Promise<void>;
}

async function fetchBookmarks(): Promise<{ items: FeedBookmark[]; urls: Set<string> }> {
  const items = await db_get_feed_bookmarks({ limit: 500, offset: 0 });
  return { items, urls: new Set(items.map((item) => item.url)) };
}

/** Shared by the Feeds entry surfaces and the in-app reader so a bookmark
 *  toggled in one place is immediately reflected everywhere else. */
export const useFeedBookmarksStore = create<FeedBookmarksState>((set, get) => ({
  items: [],
  urls: new Set(),
  pending: new Set(),
  loaded: false,
  refresh: async () => {
    try {
      const next = await fetchBookmarks();
      set({ ...next, loaded: true });
    } catch (error) {
      console.error("[feedBookmarks] refresh failed:", error);
    }
  },
  toggle: async (input) => {
    const { urls, pending } = get();
    if (pending.has(input.url)) return urls.has(input.url);
    const wasBookmarked = urls.has(input.url);
    const nextBookmarked = !wasBookmarked;
    set((s) => {
      const nextPending = new Set(s.pending);
      nextPending.add(input.url);
      const nextUrls = new Set(s.urls);
      if (nextBookmarked) nextUrls.add(input.url);
      else nextUrls.delete(input.url);
      const nextItems = nextBookmarked
        ? [{
            id: -Date.now(),
            url: input.url,
            title: input.title,
            feed_title: input.feedTitle,
            domain: input.domain,
            summary: input.summary,
            image_url: input.imageUrl,
            audio_url: input.audioUrl,
            audio_duration: input.audioDuration,
            hn_item_id: input.hnItemId,
            published: input.published,
            created_at: new Date().toISOString(),
          }, ...s.items.filter((item) => item.url !== input.url)]
        : s.items.filter((item) => item.url !== input.url);
      return { pending: nextPending, urls: nextUrls, items: nextItems, loaded: true };
    });
    try {
      const created = await db_toggle_feed_bookmark({
        url: input.url,
        title: input.title,
        feedTitle: input.feedTitle,
        domain: input.domain,
        summary: input.summary,
        imageUrl: input.imageUrl,
        audioUrl: input.audioUrl,
        audioDuration: input.audioDuration,
        hnItemId: input.hnItemId,
        published: input.published,
      });
      await get().refresh();
      return created;
    } catch (error) {
      console.error("[feedBookmarks] toggle failed:", error);
      await get().refresh();
      return wasBookmarked;
    } finally {
      set((s) => {
        const nextPending = new Set(s.pending);
        nextPending.delete(input.url);
        return { pending: nextPending };
      });
    }
  },
  remove: async (url) => {
    if (get().pending.has(url)) return;
    set((s) => {
      const nextPending = new Set(s.pending);
      nextPending.add(url);
      return { pending: nextPending };
    });
    try {
      await db_remove_feed_bookmark({ url });
      await get().refresh();
    } catch (error) {
      console.error("[feedBookmarks] remove failed:", error);
      await get().refresh();
    } finally {
      set((s) => {
        const nextPending = new Set(s.pending);
        nextPending.delete(url);
        return { pending: nextPending };
      });
    }
  },
}));
import { create } from "zustand";

export interface PendingBrowse {
  url: string;
  title: string;
  domain: string;
  audioUrl: string | null;
  feedTitle: string;
  hnItemId: number | null;
}

interface FeedsNavState {
  /** The article currently open in the Feeds page's in-app reader. Lives here —
   *  not in FeedsPage state — so leaving for another page (Settings, Dashboard…)
   *  and coming back restores the article instead of dumping the user on the
   *  feed list, and so other surfaces (player bar, dashboard widget) can open
   *  one directly. Null when the feed list is showing. */
  browse: PendingBrowse | null;
  setBrowse: (b: PendingBrowse | null) => void;
}

export const useFeedsNavStore = create<FeedsNavState>((set) => ({
  browse: null,
  setBrowse: (b) => set({ browse: b }),
}));
import { create } from "zustand";

export type HnSection = "top" | "new" | "best";

export interface HnStorySummary {
  id: number;
  title: string;
  url: string;
  by: string | null;
  score: number | null;
  time: number | null;
  descendants: number | null;
}

/** Persists the native Hacker News browser's tab/search/story-list state across
 *  mount cycles — HackerNewsSection unmounts whenever the user opens an article
 *  (FeedsMainContent swaps it for ReaderView), so plain useState would reset the
 *  section back to "Top" and refetch every time the user returns to the list. */
interface HnBrowseState {
  section: HnSection;
  query: string;
  activeQuery: string;
  stories: HnStorySummary[];
  hasMore: boolean;
  status: "loading" | "ready" | "error";
  nextSearchPage: number;
  /** Identifies which section/search the cached `stories` belong to (e.g. "section:top",
   *  "search:rust") — lets the component tell "already loaded, just remount" apart from
   *  "the user actually switched view" without refetching on every remount. */
  loadedKey: string | null;
  setSection: (s: HnSection) => void;
  setQuery: (q: string) => void;
  setActiveQuery: (q: string) => void;
  setStories: (updater: HnStorySummary[] | ((prev: HnStorySummary[]) => HnStorySummary[])) => void;
  setHasMore: (v: boolean) => void;
  setStatus: (v: "loading" | "ready" | "error") => void;
  setNextSearchPage: (n: number) => void;
  setLoadedKey: (k: string | null) => void;
}

export const useHnBrowseStore = create<HnBrowseState>((set) => ({
  section: "top",
  query: "",
  activeQuery: "",
  stories: [],
  hasMore: false,
  status: "loading",
  nextSearchPage: 0,
  loadedKey: null,
  setSection: (section) => set({ section }),
  setQuery: (query) => set({ query }),
  setActiveQuery: (activeQuery) => set({ activeQuery }),
  setStories: (updater) =>
    set((s) => ({ stories: typeof updater === "function" ? (updater as (prev: HnStorySummary[]) => HnStorySummary[])(s.stories) : updater })),
  setHasMore: (hasMore) => set({ hasMore }),
  setStatus: (status) => set({ status }),
  setNextSearchPage: (nextSearchPage) => set({ nextSearchPage }),
  setLoadedKey: (loadedKey) => set({ loadedKey }),
}));
/**
 * Dictionary recent-lookup history — port of desktop
 * `app/core/src/db/search_history.rs`.
 */
import { getDb } from "./connection";
import type { SearchHistoryItem } from "@/hooks/useDB.types";

const RECENT_LIMIT = 50;

/**
 * Records a dictionary lookup, or bumps it to the top if the word was
 * searched before — the list is "recent distinct words", not a raw log.
 *
 * Re-searching deletes and re-inserts rather than updating searched_at in
 * place: CURRENT_TIMESTAMP is only second-resolution, so two lookups within
 * the same second would tie and sort arbitrarily. A fresh autoincrement id
 * is a reliable recency order regardless of clock resolution.
 */
export async function db_add_search_history(args: { word: string }): Promise<void> {
  const word = args.word.trim().toLowerCase();
  if (word.length === 0) {
    return;
  }
  const db = getDb();
  await db.withTransactionAsync(async () => {
    await db.runAsync("DELETE FROM search_history WHERE word = ?", [word]);
    await db.runAsync(
      "INSERT INTO search_history (word, searched_at) VALUES (?, CURRENT_TIMESTAMP)",
      [word]
    );
  });
}

/** The most recent lookups, each flagged with whether the word is (now, not
 *  necessarily at search time) in the vocabulary — computed fresh on every
 *  read so it can't go stale if the word was added via a different route. */
export async function db_get_search_history(): Promise<SearchHistoryItem[]> {
  const db = getDb();
  const rows = await db.getAllAsync<{ word: string; searched_at: string; in_vocab: number }>(
    "SELECT sh.word, sh.searched_at, " +
      "EXISTS(SELECT 1 FROM words w WHERE w.word = sh.word) AS in_vocab " +
      "FROM search_history sh " +
      "ORDER BY sh.searched_at DESC, sh.id DESC " +
      "LIMIT ?",
    [RECENT_LIMIT]
  );
  return rows.map((r) => ({
    word: r.word,
    searched_at: r.searched_at,
    in_vocab: r.in_vocab !== 0,
  }));
}

export async function db_clear_search_history(): Promise<void> {
  const db = getDb();
  await db.runAsync("DELETE FROM search_history");
}

