          }
          case "li":
            return (
              <View key={key} className="mb-1.5 flex-row" style={{ paddingLeft: 4 + b.depth * 16 }}>
                <Text selectable className={`${bodyClass} w-6 text-muted-foreground`}>
                  {b.ordered ? `${b.index}.` : "•"}
                </Text>
