/**
 * MiniPlayer — persistent podcast bar above the tab bar (desktop PlayerBar,
 * mobile shape). Absolute-positioned by the screen that renders it
 * (bottom = tab bar height + safe-area inset, handled by the parent).
 */
import { Pressable, Text, View } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import * as Haptics from "expo-haptics";
import { useT } from "@/hooks/useT";
import { usePalette } from "@/lib/theme";
import { usePlayerStore } from "@/services/player";

export function MiniPlayer() {
  const t = useT();
  const p = usePalette();
  const { track, status, position, duration, toggle, seekBy, stop } = usePlayerStore();
  if (!track) return null;

  const progress = duration > 0 ? Math.min(1, position / duration) : 0;
  const playing = status === "playing";
  const loading = status === "loading";

  return (
    <View className="overflow-hidden rounded-2xl border border-border bg-card" style={{ elevation: 6, shadowColor: "#000", shadowOpacity: 0.15, shadowRadius: 8, shadowOffset: { width: 0, height: 2 } }}>
      {/* progress hairline */}
      <View className="h-[3px] w-full bg-muted">
        <View className="h-[3px] bg-primary" style={{ width: `${progress * 100}%` }} />
      </View>
      <View className="flex-row items-center gap-2 px-3 py-2">
        <Pressable
          onPress={() => void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {})}
          onLongPress={() => toggle()}
          className="h-10 w-10 items-center justify-center rounded-full bg-primary"
          style={({ pressed }) => (pressed ? { opacity: 0.8 } : undefined)}
        >
          <Ionicons
            name={loading ? "hourglass" : playing ? "pause" : "play"}
            size={18}
            color={p["primary-foreground"]}
          />
        </Pressable>
        <View className="flex-1 pr-1">
          <Text numberOfLines={1} className="text-[13px] font-semibold text-foreground">
            {track.title}
          </Text>
          <Text numberOfLines={1} className="text-[11px] text-muted-foreground">
            {track.feedTitle}
          </Text>
        </View>
        <Pressable
          onPress={() => seekBy(-15)}
          hitSlop={8}
          className="h-9 w-9 items-center justify-center"
          accessibilityLabel={t("podcast.back15")}
        >
          <Ionicons name="play-back" size={18} color={p["muted-foreground"]} />
        </Pressable>
        <Pressable
          onPress={() => seekBy(15)}
          hitSlop={8}
          className="h-9 w-9 items-center justify-center"
          accessibilityLabel={t("podcast.forward15")}
        >
          <Ionicons name="play-forward" size={18} color={p["muted-foreground"]} />
        </Pressable>
        <Pressable
          onPress={() => stop()}
          hitSlop={8}
          className="h-9 w-9 items-center justify-center"
          accessibilityLabel={t("podcast.close")}
        >
          <Ionicons name="close" size={18} color={p["muted-foreground"]} />
        </Pressable>
      </View>
    </View>
  );
}

/**
 * HnStoryRow — one Hacker News story in a FlashList. Desktop
 * HackerNewsSection renders score/comment count as icon badges (upvote /
 * chat bubble); same here, with a tappable row. React.memo for list churn.
 */
import React from "react";
import { Pressable, Text, View } from "react-native";
import { Ionicons } from "@expo/vector-icons";
import { useT } from "@/hooks/useT";
import { usePalette } from "@/lib/theme";
import { tapHaptic } from "@/components/ui";
import { useFeedBookmarksStore } from "@/store/feedBookmarksStore";
import type { HnStorySummary } from "@/services/hn";
import { domainOf, relativeTime } from "./format";

export interface HnStoryRowProps {
  story: HnStorySummary;
  onOpen: (story: HnStorySummary) => void;
  onOpenComments: (story: HnStorySummary) => void;
}

export const HnStoryRow = React.memo(function HnStoryRow({ story, onOpen, onOpenComments }: HnStoryRowProps) {
  const t = useT();
  const p = usePalette();
  const bookmarked = useFeedBookmarksStore((s) => s.urls.has(story.url));
  const toggle = useFeedBookmarksStore((s) => s.toggle);
  return (
    <Pressable
      onPress={() => {
        tapHaptic();
        onOpen(story);
      }}
      className="px-4 py-3"
      style={({ pressed }) => (pressed ? { opacity: 0.7 } : undefined)}
    >
      <Text numberOfLines={2} className="text-[15px] font-semibold leading-5 text-foreground">
        {story.title}
      </Text>
      <Text numberOfLines={1} className="mt-1 text-[12px] text-muted-foreground">
        {domainOf(story.url)}
        {story.by ? ` · ${story.by}` : ""}
        {story.time ? ` · ${relativeTime(story.time * 1000, t)}` : ""}
      </Text>
      <View className="mt-2 flex-row items-center gap-4">
        <View className="flex-row items-center gap-1">
          <Ionicons name="triangle-outline" size={13} color={p.primary} />
          <Text className="text-[12px] font-semibold text-foreground">{story.score ?? 0}</Text>
        </View>
        <Pressable
          onPress={() => {
            tapHaptic();
            onOpenComments(story);
          }}
          hitSlop={8}
          className="min-h-[28px] flex-row items-center gap-1"
          style={({ pressed }) => (pressed ? { opacity: 0.7 } : undefined)}
        >
          <Ionicons name="chatbubble-outline" size={13} color={p["muted-foreground"]} />
          <Text className="text-[12px] text-muted-foreground">{story.descendants ?? 0}</Text>
        </Pressable>
        <View className="flex-1" />
        <Pressable
          onPress={() =>
            void toggle({
              url: story.url,
              title: story.title,
              feedTitle: "Hacker News",
              domain: domainOf(story.url),
              summary: "",
              imageUrl: null,
              audioUrl: null,
              audioDuration: null,
              hnItemId: story.id,
              published: story.time ? new Date(story.time * 1000).toISOString() : "",
            })
          }
          hitSlop={10}
          className="min-h-[28px] min-w-[28px] items-center justify-center"
        >
          <Ionicons
            name={bookmarked ? "bookmark" : "bookmark-outline"}
            size={16}
            color={bookmarked ? p.primary : p["muted-foreground"]}
          />
        </Pressable>
      </View>
    </Pressable>
  );
});

