/**
 * HN tab — native Hacker News browser (desktop HackerNewsSection): section
 * segmented tabs (热门/最新/精选) + optional Algolia search, stories from
 * services/hn.ts. List state persists in hnBrowseStore across mount cycles
 * (segment switches unmount the list; the store is the "already loaded"
 * memory, mirroring the desktop's reason for that store).
 */
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { RefreshControl, View } from "react-native";
import { FlashList } from "@shopify/flash-list";
import { useRouter } from "expo-router";
import { useT } from "@/hooks/useT";
import { usePalette } from "@/lib/theme";
import { Button, Divider, EmptyState, SearchBar, SearchBar as SB, SegmentedTabs, Skeleton } from "@/components/ui";
import { fetchHnSection, searchHn, type HnStorySummary } from "@/services/hn";
import { useHnBrowseStore } from "@/store/hnBrowseStore";
import { HnStoryRow } from "./HnStoryRow";

const PAGE = 25;

/** Guard: onEndReached fires spuriously right after render on short lists. */
function makeEndReachedGuard() {
  let ready = false;
  let timer: ReturnType<typeof setTimeout> | null = null;
  return {
    arm() {
      ready = false;
      if (timer) clearTimeout(timer);
      timer = setTimeout(() => {
        ready = true;
      }, 400);
    },
    isArmed: () => ready,
  };
}

export function HnSegment() {
  const t = useT();
  const p = usePalette();
  const router = useRouter();
  const s = useHnBrowseStore();
  const guard = useMemo(makeEndReachedGuard, []);
  const [refreshing, setRefreshing] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);

  const loadedKeyFor = useCallback(
    () => (s.activeQuery ? `search:${s.activeQuery}` : `section:${s.section}`),
    [s.activeQuery, s.section]
  );

  const loadFirstPage = useCallback(
    async (opts?: { force?: boolean }) => {
      const key = loadedKeyFor();
      if (!opts?.force && s.loadedKey === key && s.stories.length > 0) return;
      s.setStatus("loading");
      s.setLoadedKey(key);
      try {
        if (s.activeQuery) {
          const page = await searchHn(s.activeQuery, 0);
          s.setStories(page.stories);
          s.setHasMore(page.page + 1 < page.total_pages);
          s.setNextSearchPage(1);
        } else {
          const pageData = await fetchHnSection(s.section, 0, PAGE);
          s.setStories(pageData.stories);
          s.setHasMore(PAGE < pageData.total);
        }
        s.setStatus("ready");
        guard.arm();
      } catch (e) {
        console.error("[hn] load failed:", e);
        s.setStatus("error");
      }
    },
    // s object identity changes on updates — destructure the functions we use.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [s.activeQuery, s.section, s.loadedKey, s.loadedKey === null, guard]
  );

  useEffect(() => {
    void loadFirstPage();
  }, [loadFirstPage]);

  const refresh = useCallback(async () => {
    setRefreshing(true);
    await loadFirstPage({ force: true });
    setRefreshing(false);
  }, [loadFirstPage]);

  const loadMore = useCallback(async () => {
    if (loadingMore || !s.hasMore || s.status !== "ready" || s.stories.length === 0) return;
    if (!guard.isArmed()) return;
    setLoadingMore(true);
    try {
      if (s.activeQuery) {
        const page = await searchHn(s.activeQuery, s.nextSearchPage);
        s.setStories((prev) => {
          const seen = new Set(prev.map((x) => x.id));
          return [...prev, ...page.stories.filter((x) => !seen.has(x.id))];
        });
        s.setHasMore(page.page + 1 < page.total_pages);
        s.setNextSearchPage(page.page + 1);
