      hitSlop={8}
      className="min-h-[40px] min-w-[40px] items-center justify-center"
      style={({ pressed }) => (pressed ? { opacity: 0.6 } : undefined)}
    >
      <Ionicons name={name} size={20} color={p.foreground} />
    </Pressable>
  );
}

